static char __jcc_std_stddef_h[338] = "/* stddef.h - standard definitions for JCC C compiler */\n\n#ifndef __STDDEF_H\n#define __STDDEF_H\n\ntypedef long ptrdiff_t;\ntypedef long size_t;\ntypedef int wchar_t;\n\n#define NULL ((void*)0)\n\n/* offsetof macro - works with standard layout structs */\n#define offsetof(type, member) ((size_t) &(((type *)0)->member))\n\n#endif /* __STDDEF_H */\n";
static char __jcc_std_stdint_h[814] = "/* stdint.h - fixed-width integer types for JCC C compiler */\n\n#ifndef __STDINT_H\n#define __STDINT_H\n\n/* On this VM, long is 8 bytes */\ntypedef signed char int8_t;\ntypedef short int16_t;\ntypedef int int32_t;\ntypedef long int64_t;\n\ntypedef unsigned char uint8_t;\ntypedef unsigned short uint16_t;\ntypedef unsigned int uint32_t;\ntypedef unsigned long uint64_t;\n\ntypedef long intptr_t;\ntypedef unsigned long uintptr_t;\n\n#define INT8_MIN   (-128)\n#define INT8_MAX   127\n#define INT16_MIN  (-32768)\n#define INT16_MAX  32767\n#define INT32_MIN  (-2147483648)\n#define INT32_MAX  2147483647\n#define INT64_MIN  (-9223372036854775807L-1)\n#define INT64_MAX  9223372036854775807L\n\n#define UINT8_MAX  255\n#define UINT16_MAX 65535\n#define UINT32_MAX 4294967295U\n#define UINT64_MAX 18446744073709551615UL\n\n#endif /* __STDINT_H */\n";
static char __jcc_std_stdio_h[3652] = "/*\n * stdio.h - Standard I/O functions for JCC VM\n */\n\n#ifndef __STDIO_H\n#define __STDIO_H\n\n#include \"stdarg.h\"\n#include \"stddef.h\"\n\n// FILE type (opaque pointer to host FILE)\ntypedef void FILE;\n\n// Standard streams (accessed via getter functions)\nextern FILE* __jcc_stdin(void);\nextern FILE* __jcc_stdout(void);\nextern FILE* __jcc_stderr(void);\n#define stdin __jcc_stdin()\n#define stdout __jcc_stdout()\n#define stderr __jcc_stderr()\n\n/* Types and macros from the C standard */\ntypedef long fpos_t;\n\n/* Buffering and limits */\n#ifndef BUFSIZ\n#define BUFSIZ 8192\n#endif\n\n#ifndef EOF\n#define EOF (-1)\n#endif\n\n#ifndef FILENAME_MAX\n#define FILENAME_MAX 4096\n#endif\n\n#ifndef FOPEN_MAX\n#define FOPEN_MAX 20\n#endif\n\n#ifndef L_tmpnam\n#define L_tmpnam 20\n#endif\n\n#ifndef TMP_MAX\n#define TMP_MAX 238328\n#endif\n\n/* Seek constants */\n#ifndef SEEK_SET\n#define SEEK_SET 0\n#define SEEK_CUR 1\n#define SEEK_END 2\n#endif\n\n/* setvbuf modes */\n#ifndef _IOFBF\n#define _IOFBF 0\n#define _IOLBF 1\n#define _IONBF 2\n#endif\n\n// ==================================================\n// Variadic function declarations \n// ==================================================\n// Supported via platform inline assembly\n\n// Printf family\nextern int printf(const char *fmt, ...);\nextern int fprintf(FILE *stream, const char *fmt, ...);\nextern int sprintf(char *str, const char *fmt, ...);\nextern int snprintf(char *str, size_t size, const char *fmt, ...);\n\n// Scanf family\nextern int scanf(const char *fmt, ...);\nextern int sscanf(const char *str, const char *fmt, ...);\nextern int fscanf(FILE *stream, const char *fmt, ...);\n\n// V* variants (take va_list) - Note: va_list manipulation not fully supported in VM\n// These are provided for completeness but may not work as expected\nextern int vprintf(char *fmt, va_list ap);\nextern int vsprintf(char *str, char *fmt, va_list ap);\nextern int vsnprintf(char *str, long size, char *fmt, va_list ap);\nextern int vfprintf(FILE *stream, char *fmt, va_list ap);\nextern int vscanf(char *fmt, va_list ap);\nextern int vsscanf(char *str, char *fmt, va_list ap);\nextern int vfscanf(FILE *stream, char *fmt, va_list ap);\n\n// ==================================================\n// Common non-variadic stdio functions (both modes)\n// ==================================================\n\n\nextern int remove(const char* filename);\nextern int rename(const char* old, const char* new);\nextern FILE* tmpfile(void);\nextern char* tmpnam(char* s);\nextern int fclose(FILE* stream);\nextern int fflush(FILE* stream);\nextern FILE* fopen(const char* filename, const char* mode);\nextern FILE* freopen(const char* filename, const char* mode, FILE* stream);\nextern void setbuf(FILE* stream, char* buf);\nextern int setvbuf(FILE* stream, char* buf, int mode, size_t size);\nextern int fgetc(FILE* stream);\nextern char* fgets(char* s, int n, FILE* stream);\nextern int fputc(int c, FILE* stream);\nextern int fputs(const char* s, FILE* stream);\nextern int getc(FILE* stream);\nextern int getchar(void);\nextern int putc(int c, FILE* stream);\nextern int putchar(int c);\nextern int puts(const char* s);\nextern int ungetc(int c, FILE* stream);\nextern size_t fread(void* ptr, size_t size, size_t nmemb, FILE* stream);\nextern size_t fwrite(const void* ptr, size_t size, size_t nmemb, FILE* stream);\nextern int fgetpos(FILE* stream, fpos_t* pos);\nextern int fseek(FILE* stream, long int offset, int whence);\nextern int fsetpos(FILE* stream, const fpos_t* pos);\nextern long int ftell(FILE* stream);\nextern void rewind(FILE* stream);\nextern void clearerr(FILE* stream);\nextern int feof(FILE* stream);\nextern int ferror(FILE* stream);\nextern void perror(const char* s);\n\n#endif // __STDIO_H\n";
static char __jcc_std_stdlib_h[3044] = "// Standard library function declarations for FFI\n// This header provides declarations for C standard library functions\n// that are registered in the VM's FFI and can be called directly\n\n#ifndef __STDLIB_H\n#define __STDLIB_H \n\n#include \"stddef.h\"\n\n/* EXIT macros */\n#ifndef EXIT_SUCCESS\n#define EXIT_SUCCESS 0\n#endif\n#ifndef EXIT_FAILURE\n#define EXIT_FAILURE 1\n#endif\n\n// typedef unsigned int once_flag;\n// extern void call_once(once_flag* flag, void (*func)(void));\n\nextern double atof(const char* nptr);\nextern int atoi(const char* nptr);\nextern long int atol(const char* nptr);\nextern long long int atoll(const char* nptr);\n// extern int strfromd(char* s, size_t n, const char* format, double fp);\n// extern int strfromf(char* s, size_t n, const char* format, float fp);\n// extern int strfroml(char* s, size_t n, const char* format, long double fp);\nextern double strtod(const char* nptr, char** endptr);\nextern float strtof(const char* nptr, char** endptr);\nextern long double strtold(const char* nptr, char** endptr);\nextern long int strtol(const char* nptr, char** endptr, int base);\nextern long long int strtoll(const char* nptr, char** endptr, int base);\nextern unsigned long int strtoul(const char* nptr, char** endptr, int base);\nextern unsigned long long int strtoull(const char* nptr, char** endptr, int base);\n\nextern int rand(void);\nextern void srand(unsigned int seed);\nextern void* aligned_alloc(size_t alignment, size_t size);\nextern void* calloc(size_t nmemb, size_t size);\nextern void free(void* ptr);\n// extern void free_sized(void* ptr, size_t size);\n// extern void free_aligned_sized(void* ptr, size_t alignment, size_t size);\nextern void* malloc(size_t size);\nextern void* realloc(void* ptr, size_t size);\nextern void abort(void);\nextern int atexit(void (*func)(void));\nextern int at_quick_exit(void (*func)(void));\nextern void exit(int status);\nextern void _Exit(int status);\nextern char* getenv(const char* name);\nextern void quick_exit(int status);\nextern int system(const char* string);\nextern int posix_memalign(void** memptr, size_t alignment, size_t size);\nextern void* bsearch(const void* key, void* base, size_t nmemb, size_t size, int (*compar)(const void* , const void* ));\nextern void qsort(void* base, size_t nmemb, size_t size, int (*compar)(const void* , const void* ));\nextern int abs(int j);\nextern long int labs(long int j);\nextern long long int llabs(long long int j);\n\ntypedef struct { int quot; int rem; } div_t;\ntypedef struct { long quot; long rem; } ldiv_t;\ntypedef struct { long long quot; long long rem; } lldiv_t;\n\nextern div_t div(int numer, int denom);\nextern ldiv_t ldiv(long int numer, long int denom);\nextern lldiv_t lldiv(long long int numer, long long int denom);\n\nextern int mblen(const char* s, size_t n);\nextern int mbtowc(wchar_t* pwc, const char* s, size_t n);\nextern int wctomb(char* s, wchar_t wc);\n\nextern size_t mbstowcs(wchar_t* pwcs, const char* s, size_t n);\nextern size_t wcstombs(char* s, const wchar_t* pwcs, size_t n);\nextern size_t memalignment(const void* p);\n\n#endif\n";
static char __jcc_std_stdnoreturn_h[85] = "#ifndef __STDNORETURN_H\n#define __STDNORETURN_H\n\n#define noreturn _Noreturn\n\n#endif\n";
static char __jcc_std_string_h[1898] = "/* string.h - string manipulation functions for JCC C compiler */\n\n#ifndef __STRING_H\n#define __STRING_H\n\nextern void *memcpy(void *dest, const void *src, long n);\nextern void *memmove(void *dest, const void *src, long n);\nextern void *memset(void *s, int c, long n);\nextern int memcmp(const void *s1, const void *s2, long n);\n\nextern long strlen(const char *s);\nextern char *strcpy(char *dest, const char *src);\nextern char *strncpy(char *dest, const char *src, long n);\nextern char *strcat(char *dest, const char *src);\nextern char *strncat(char *dest, const char *src, long n);\nextern int strcmp(const char *s1, const char *s2);\nextern int strncmp(const char *s1, const char *s2, long n);\nextern char *strchr(const char *s, int c);\nextern char *strrchr(const char *s, int c);\nextern char *strstr(const char *haystack, const char *needle);\nextern long strxfrm(char *dest, const char *src, long n);\nextern char* strerror(int errnum);\n\n// extern char* strcpy_s(char *dest, long destsz, const char *src);\n// extern char* strncpy_s(char *dest, long destsz, const char *src, long n);\n// extern char* strcat_s(char *dest, long destsz, const char *src);\n// extern char* strncat_s(char *dest, long destsz, const char *src, long n);\nextern char* strdup(const char *s);\nextern char* strndup(const char *s, long n);\n// extern long strnlen_s(const char *s, long maxsize);\n// extern char* strtok_s(char *str, const char *delim, char **context);\n// extern void* memset_explicit(void *s, int c, long n);\n// extern int memset_s(void *s, long smax, int c, long n);\n// extern void* memcpy_s(void *dest, long destsz, const void *src, long n);\n// extern void* memmove_s(void *dest, long destsz, const void *src, long n);\nextern void* memccpy(void *dest, const void *src, int c, long n);\n// extern int strerror_s(char *buf, long bufsz, int errnum);\n// extern long strerrorlen_s(int errnum);\n\n#endif /* __STRING_H */\n";
static char __jcc_std_strings_h[595] = "/* strings.h - POSIX string functions supplement for JCC */\n\n#ifndef __STRINGS_H\n#define __STRINGS_H\n\n#ifdef _WIN32\n#error \"<strings.h> is only available on POSIX targets in JCC\"\n#endif\n\n#include \"stddef.h\"\n\nextern int strcasecmp(const char *s1, const char *s2);\nextern int strncasecmp(const char *s1, const char *s2, size_t n);\nextern void bzero(void *s, size_t n);\nextern void bcopy(const void *src, void *dst, size_t n);\nextern int bcmp(const void *s1, const void *s2, size_t n);\nextern char *index(const char *s, int c);\nextern char *rindex(const char *s, int c);\n\n#endif /* __STRINGS_H */\n";
static char __jcc_std_sys_cdefs_h[754] = "/*\n * JCC wrapper for sys/cdefs.h\n * \n * This stub includes Availability.h first (to set up JCC compatibility macros)\n * then includes the real sys/cdefs.h from the system include path.\n * \n * The order matters because sys/cdefs.h uses __GNUC__ and __has_attribute\n * to define macros that JCC cannot parse (like __attribute__((__always_inline__))).\n * By including Availability.h first, we ensure __has_attribute returns 0\n * and __attribute__ is stripped.\n */\n\n#ifndef _JCC_SYS_CDEFS_H_\n#define _JCC_SYS_CDEFS_H_\n\n/* Include JCC's Availability.h stub first to set up compatibility macros */\n#include <Availability.h>\n\n/* Now include the real sys/cdefs.h - but we need to use include_next */\n#include_next <sys/cdefs.h>\n\n#endif /* _JCC_SYS_CDEFS_H_ */\n";
static char __jcc_std_sys_mman_h[1180] = "/* sys/mman.h - memory management declarations for JCC */\n\n#ifndef __SYS_MMAN_H\n#define __SYS_MMAN_H\n\n#ifdef _WIN32\n#error \"<sys/mman.h> is only available on POSIX targets in JCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define PROT_NONE  0x00\n#define PROT_READ  0x01\n#define PROT_WRITE 0x02\n#define PROT_EXEC  0x04\n\n#ifdef __APPLE__\n#define MAP_SHARED    0x0001\n#define MAP_PRIVATE   0x0002\n#define MAP_FIXED     0x0010\n#define MAP_ANON      0x1000\n#define MAP_ANONYMOUS MAP_ANON\n#else\n#define MAP_SHARED    0x01\n#define MAP_PRIVATE   0x02\n#define MAP_FIXED     0x10\n#define MAP_ANONYMOUS 0x20\n#define MAP_ANON      MAP_ANONYMOUS\n#endif\n\n#define MS_ASYNC      0x0001\n#define MS_SYNC       0x0002\n#define MS_INVALIDATE 0x0004\n\n#define MADV_NORMAL     0\n#define MADV_RANDOM     1\n#define MADV_SEQUENTIAL 2\n#define MADV_WILLNEED   3\n#define MADV_DONTNEED   4\n\nextern void *mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset);\nextern int munmap(void *addr, size_t length);\nextern int mprotect(void *addr, size_t len, int prot);\nextern int msync(void *addr, size_t len, int flags);\nextern int posix_madvise(void *addr, size_t len, int advice);\n\n#endif /* __SYS_MMAN_H */\n";
static char __jcc_std_sys_socket_h[1309] = "/* sys/socket.h - socket declarations for JCC */\n\n#ifndef __SYS_SOCKET_H\n#define __SYS_SOCKET_H\n\n#ifdef _WIN32\n#error \"<sys/socket.h> is only available on POSIX targets in JCC\"\n#endif\n\n#include \"sys/types.h\"\n\n#ifdef __APPLE__\nstruct sockaddr {\n    unsigned char sa_len;\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#else\nstruct sockaddr {\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#endif\n\n#define SOCK_STREAM 1\n#define SOCK_DGRAM  2\n#define SOCK_RAW    3\n\n#ifdef __APPLE__\n#define SOL_SOCKET   0xffff\n#define SO_REUSEADDR 0x0004\n#else\n#define SOL_SOCKET   1\n#define SO_REUSEADDR 2\n#endif\n\n#define SHUT_RD   0\n#define SHUT_WR   1\n#define SHUT_RDWR 2\n\nextern int socket(int domain, int type, int protocol);\nextern int bind(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int listen(int socket, int backlog);\nextern int accept(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int connect(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int setsockopt(int socket, int level, int option_name,\n                      const void *option_value, socklen_t option_len);\nextern int getsockname(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int shutdown(int socket, int how);\n\n#endif /* __SYS_SOCKET_H */\n";
static char __jcc_std_sys_stat_h[2474] = "/* sys/stat.h - file status for JCC */\n\n#ifndef __SYS_STAT_H\n#define __SYS_STAT_H\n\n#ifdef _WIN32\n#error \"<sys/stat.h> is only available on POSIX targets in JCC\"\n#endif\n\n#include \"sys/types.h\"\n\n/* Pull in struct timespec and time_t */\n#include \"../time.h\"\n\n#ifdef __APPLE__\n\nstruct stat {\n    dev_t     st_dev;\n    mode_t    st_mode;\n    nlink_t   st_nlink;\n    ino_t     st_ino;\n    uid_t     st_uid;\n    gid_t     st_gid;\n    dev_t     st_rdev;\n    struct timespec st_atimespec;\n    struct timespec st_mtimespec;\n    struct timespec st_ctimespec;\n    struct timespec st_birthtimespec;\n    off_t     st_size;\n    blkcnt_t  st_blocks;\n    blksize_t st_blksize;\n    unsigned int st_flags;\n    unsigned int st_gen;\n    int       st_lspare;\n    long long st_qspare[2];\n};\n\n#else\n/* Linux / generic POSIX */\n\nstruct stat {\n    unsigned long st_dev;\n    unsigned long st_ino;\n    unsigned long st_nlink;\n    unsigned int  st_mode;\n    unsigned int  st_uid;\n    unsigned int  st_gid;\n    unsigned int  __pad0;\n    unsigned long st_rdev;\n    long          st_size;\n    long          st_blksize;\n    long          st_blocks;\n    struct timespec st_atim;\n    struct timespec st_mtim;\n    struct timespec st_ctim;\n    long          __unused[3];\n};\n\n#endif\n\n#define S_IFMT   0xF000\n#define S_IFIFO  0x1000\n#define S_IFCHR  0x2000\n#define S_IFDIR  0x4000\n#define S_IFBLK  0x6000\n#define S_IFREG  0x8000\n#define S_IFLNK  0xA000\n#define S_IFSOCK 0xC000\n\n#define S_ISFIFO(m) (((m) & S_IFMT) == S_IFIFO)\n#define S_ISCHR(m)  (((m) & S_IFMT) == S_IFCHR)\n#define S_ISDIR(m)  (((m) & S_IFMT) == S_IFDIR)\n#define S_ISBLK(m)  (((m) & S_IFMT) == S_IFBLK)\n#define S_ISREG(m)  (((m) & S_IFMT) == S_IFREG)\n#define S_ISLNK(m)  (((m) & S_IFMT) == S_IFLNK)\n#define S_ISSOCK(m) (((m) & S_IFMT) == S_IFSOCK)\n\n#define S_IRWXU  0700\n#define S_IRUSR  0400\n#define S_IWUSR  0200\n#define S_IXUSR  0100\n#define S_IRWXG  0070\n#define S_IRGRP  0040\n#define S_IWGRP  0020\n#define S_IXGRP  0010\n#define S_IRWXO  0007\n#define S_IROTH  0004\n#define S_IWOTH  0002\n#define S_IXOTH  0001\n\n#define S_ISUID  04000\n#define S_ISGID  02000\n#define S_ISVTX  01000\n\nextern int stat(const char *path, struct stat *buf);\nextern int fstat(int fd, struct stat *buf);\nextern int lstat(const char *path, struct stat *buf);\nextern int chmod(const char *path, mode_t mode);\nextern int mkdir(const char *path, mode_t mode);\nextern int mkfifo(const char *path, mode_t mode);\nextern mode_t umask(mode_t cmask);\n\n#endif /* __SYS_STAT_H */\n";
static char __jcc_std_sys_time_h[994] = "/* sys/time.h - time types for JCC */\n\n#ifndef __SYS_TIME_H\n#define __SYS_TIME_H\n\n#ifdef _WIN32\n#error \"<sys/time.h> is only available on POSIX targets in JCC\"\n#endif\n\n#include \"time.h\"\n\nstruct timeval {\n    long tv_sec;\n    long tv_usec;\n};\n\nstruct timezone {\n    int tz_minuteswest;\n    int tz_dsttime;\n};\n\nextern int gettimeofday(struct timeval *tv, struct timezone *tz);\nextern int settimeofday(const struct timeval *tv, const struct timezone *tz);\n\n#define timeradd(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec + (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec + (b)->tv_usec; \\\n    if ((res)->tv_usec >= 1000000) { \\\n        (res)->tv_sec++; \\\n        (res)->tv_usec -= 1000000; \\\n    } \\\n} while (0)\n\n#define timersub(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec - (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec - (b)->tv_usec; \\\n    if ((res)->tv_usec < 0) { \\\n        (res)->tv_sec--; \\\n        (res)->tv_usec += 1000000; \\\n    } \\\n} while (0)\n\n#endif /* __SYS_TIME_H */\n";
static char __jcc_std_sys_types_h[1176] = "/* sys/types.h - basic system types for JCC */\n\n#ifndef __SYS_TYPES_H\n#define __SYS_TYPES_H\n\n#ifdef _WIN32\n#error \"<sys/types.h> is only available on POSIX targets in JCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef int               dev_t;\ntypedef unsigned long long ino_t;\ntypedef unsigned short    mode_t;\ntypedef unsigned short    nlink_t;\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long long         off_t;\ntypedef int               pid_t;\ntypedef int               blksize_t;\ntypedef long long         blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned char     sa_family_t;\ntypedef unsigned int      socklen_t;\n#else\n/* Linux / generic POSIX */\ntypedef unsigned long     dev_t;\ntypedef unsigned long     ino_t;\ntypedef unsigned int      mode_t;\ntypedef unsigned long     nlink_t;\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long              off_t;\ntypedef int               pid_t;\ntypedef long              blksize_t;\ntypedef long              blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned short    sa_family_t;\ntypedef unsigned int      socklen_t;\n#endif\n\n#endif /* __SYS_TYPES_H */\n";
static char __jcc_std_sys_wait_h[753] = "/* sys/wait.h - process wait declarations for JCC */\n\n#ifndef __SYS_WAIT_H\n#define __SYS_WAIT_H\n\n#ifdef _WIN32\n#error \"<sys/wait.h> is only available on POSIX targets in JCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define WNOHANG    1\n#define WUNTRACED  2\n\n#define WIFEXITED(status)   (((status) & 0x7f) == 0)\n#define WEXITSTATUS(status) (((status) >> 8) & 0xff)\n#define WIFSIGNALED(status) ((((status) & 0x7f) > 0) && (((status) & 0x7f) < 0x7f))\n#define WTERMSIG(status)    ((status) & 0x7f)\n#define WIFSTOPPED(status)  (((status) & 0xff) == 0x7f)\n#define WSTOPSIG(status)    WEXITSTATUS(status)\n#define WCOREDUMP(status)   ((status) & 0x80)\n\nextern pid_t wait(int *status);\nextern pid_t waitpid(pid_t pid, int *status, int options);\n\n#endif /* __SYS_WAIT_H */\n";
static char __jcc_std_termios_h[1505] = "/* termios.h - terminal I/O declarations for JCC */\n\n#ifndef __TERMIOS_H\n#define __TERMIOS_H\n\n#ifdef _WIN32\n#error \"<termios.h> is only available on POSIX targets in JCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef unsigned long tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned long speed_t;\n#define NCCS 20\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#else\ntypedef unsigned int tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned int speed_t;\n#define NCCS 32\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_line;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#endif\n\n#define TCSANOW   0\n#define TCSADRAIN 1\n#define TCSAFLUSH 2\n\n#define VEOF   0\n#define VEOL   1\n#define VERASE 3\n#define VINTR  8\n#define VMIN   16\n#define VTIME  17\n\n#define BRKINT  0x00000002\n#define ICRNL   0x00000100\n#define IXON    0x00000200\n#define OPOST   0x00000001\n#define CS8     0x00000300\n#define CREAD   0x00000800\n#define ECHO    0x00000008\n#define ICANON  0x00000100\n#define ISIG    0x00000080\n\n#define B0       0\n#define B9600    9600\n#define B19200   19200\n#define B38400   38400\n#define B115200  115200\n\nextern int tcgetattr(int fildes, struct termios *termios_p);\nextern int tcsetattr(int fildes, int optional_actions,\n                     const struct termios *termios_p);\n\n#endif /* __TERMIOS_H */\n";
static char __jcc_std_tgmath_h[1668] = "/* tgmath.h - type-generic math macros for JCC */\n\n#ifndef __TGMATH_H\n#define __TGMATH_H\n\n#include \"math.h\"\n#include \"complex.h\"\n\n#define __jcc_tg_unary(x, fd, ff, fl) _Generic((x), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x)\n\n#define __jcc_tg_binary(x, y, fd, ff, fl) _Generic(((x) + (y)), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x, y)\n\n#define __jcc_tg_real_or_complex_abs(x) _Generic((x), \\\n    long double _Complex: cabsl(x), \\\n    double _Complex: cabs(x), \\\n    float _Complex: cabsf(x), \\\n    long double: fabsl(x), \\\n    float: fabsf(x), \\\n    default: fabs(x))\n\n#define acos(x) __jcc_tg_unary((x), acos, acosf, acosl)\n#define asin(x) __jcc_tg_unary((x), asin, asinf, asinl)\n#define atan(x) __jcc_tg_unary((x), atan, atanf, atanl)\n#define cos(x) __jcc_tg_unary((x), cos, cosf, cosl)\n#define sin(x) __jcc_tg_unary((x), sin, sinf, sinl)\n#define tan(x) __jcc_tg_unary((x), tan, tanf, tanl)\n#define exp(x) __jcc_tg_unary((x), exp, expf, expl)\n#define log(x) __jcc_tg_unary((x), log, logf, logl)\n#define sqrt(x) __jcc_tg_unary((x), sqrt, sqrtf, sqrtl)\n#define fabs(x) __jcc_tg_real_or_complex_abs((x))\n#define floor(x) __jcc_tg_unary((x), floor, floorf, floorl)\n#define ceil(x) __jcc_tg_unary((x), ceil, ceilf, ceill)\n#define trunc(x) __jcc_tg_unary((x), trunc, truncf, truncl)\n#define round(x) __jcc_tg_unary((x), round, roundf, roundl)\n#define pow(x, y) __jcc_tg_binary((x), (y), pow, powf, powl)\n#define fmod(x, y) __jcc_tg_binary((x), (y), fmod, fmodf, fmodl)\n#define atan2(x, y) __jcc_tg_binary((x), (y), atan2, atan2f, atan2l)\n#define hypot(x, y) __jcc_tg_binary((x), (y), hypot, hypotf, hypotl)\n\n#endif /* __TGMATH_H */\n";
static char __jcc_std_time_h[1185] = "/* time.h - time functions for JCC C compiler */\n\n#ifndef __TIME_H\n#define __TIME_H\n\n#include \"stddef.h\"\n\ntypedef long clock_t;\ntypedef long time_t;\n\nstruct timespec {\n    time_t tv_sec;\n    long tv_nsec;\n};\n\n#define TIME_UTC 1\n\nstruct tm {\n    int tm_sec;\n    int tm_min;\n    int tm_hour;\n    int tm_mday;\n    int tm_mon;\n    int tm_year;\n    int tm_wday;\n    int tm_yday;\n    int tm_isdst;\n};\n\nextern clock_t clock(void);\nextern double difftime(time_t time1, time_t time0);\nextern time_t mktime(struct tm *timeptr);\n// extern time_t timegm(const struct tm *timeptr);\nextern time_t time(time_t *t);\nextern int timespec_get(struct timespec *ts, int base);\n// extern int timespec_getres(struct timespec *ts, int base);\nextern char *asctime(const struct tm *tm); // deprecated\nextern char *ctime(const time_t *timer); // deprecated\nextern struct tm *gmtime(const time_t *timer);\nextern struct tm *gmtime_r(const time_t *timer, struct tm *result);\nextern struct tm *localtime(const time_t *timer);\nextern struct tm *localtime_r(const time_t *timer, struct tm *result);\nextern size_t strftime(char *s, size_t maxsize, const char *format, const struct tm *timeptr);\n\n#endif /* __TIME_H */\n";
